$u=require_login(); $canCreate=can_create_meetings($pdo,$u); $canManage=can_manage_meetings($pdo,$u);
function sm_meeting(PDO $pdo,int $id): array {$q=$pdo->prepare('SELECT * FROM meetings WHERE id=?');$q->execute([$id]);$m=$q->fetch();if(!$m){http_response_code(404);exit('Stammtisch nicht gefunden.');}return $m;}
function sm_active(array $m): bool{return in_array($m['status'],['poll','scheduled'],true);}
function sm_push(PDO $pdo,string $title,string $body): void {send_push_to_all_active_users($pdo,$title,$body,'/stammtisch.php','meeting');}
function sm_order(PDO $pdo,int $meeting,array $ids): void {$q=$pdo->prepare('SELECT id,title FROM meeting_agenda_items WHERE meeting_id=?');$q->execute([$meeting]);$rows=$q->fetchAll();$valid=[];$last=[];foreach($rows as $row){if(mb_strtolower(trim($row['title']))==='sonstiges')$last[]=(int)$row['id'];else $valid[(int)$row['id']]=true;}$ids=array_values(array_filter($ids,fn($id)=>isset($valid[$id])));foreach(array_keys($valid) as $id)if(!in_array($id,$ids,true))$ids[]=$id;$ids=array_merge($ids,$last);$q=$pdo->prepare('UPDATE meeting_agenda_items SET sort_order=? WHERE meeting_id=? AND id=?');foreach($ids as $n=>$id)$q->execute([($n+1)*10,$meeting,$id]);}

if($_SERVER['REQUEST_METHOD']==='POST'){
