    $q=$pdo->prepare('SELECT id,starts_at_utc FROM meeting_poll_options WHERE meeting_id=?');$q->execute([$m['id']]);$existing=[];foreach($q->fetchAll() as $row)$existing[(int)$row['id']]=$row['starts_at_utc'];
    $final=[];$update=[];$delete=[];
    foreach($existing as $oid=>$old){if(isset($_POST['opt_delete'][$oid])){$delete[]=$oid;continue;}$raw=(string)($_POST['opt_start'][$oid]??'');$v=meeting_local_to_utc(substr($raw,0,10),substr($raw,11,5));if(!$v)throw new RuntimeException('Ungültiger Termin.');$final[$oid]=$v;if($v!==$old)$update[$oid]=$v;}
