    $all=array_merge(array_values($final),array_keys($add));if(count($all)!==count(array_unique($all)))throw new RuntimeException('Terminoptionen müssen unterschiedlich sein.');if(count($all)<2)throw new RuntimeException('Mindestens zwei Terminoptionen müssen bleiben.');
    $pdo->beginTransaction();
