    $q=$pdo->prepare('DELETE FROM meeting_poll_options WHERE id=? AND meeting_id=?');foreach($delete as $oid)$q->execute([$oid,$m['id']]);
    $q=$pdo->prepare('UPDATE meeting_poll_options SET starts_at_utc=? WHERE id=? AND meeting_id=?');foreach($update as $oid=>$v)$q->execute([$v,$oid,$m['id']]);
    $q=$pdo->prepare('INSERT INTO meeting_poll_options(meeting_id,starts_at_utc) VALUES(?,?)');foreach(array_keys($add) as $v)$q->execute([$m['id'],$v]);
    meeting_audit($pdo,$m['id'],$u['id'],'poll_updated','Terminfindung geändert');$pdo->commit();
