   } else {
    $reopen=$action==='reopen';if($reopen){if(!can_reopen_protocols()||$m['status']!=='completed')throw new RuntimeException('Nur Schriftführer oder Admin dürfen ein abgeschlossenes Protokoll öffnen.');$pdo->prepare("UPDATE meetings SET status='scheduled',completed_at=NULL,completed_by=NULL,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?")->execute([$u['id'],$m['id']]);meeting_audit($pdo,$m['id'],$u['id'],'reopened','Protokoll wieder geöffnet');flash('success','Protokoll wieder geöffnet.');}
    else {if(!$canManage||!sm_active($m))throw new RuntimeException('Keine Berechtigung oder Protokoll abgeschlossen.');
     if($action==='details'){$title=trim((string)$_POST['title']);$date=meeting_local_to_utc(substr((string)$_POST['starts_at'],0,10),substr((string)$_POST['starts_at'],11,5));if(mb_strlen($title)<3||!$date)throw new RuntimeException('Überschrift und Termin sind erforderlich.');$changed=$date!==$m['starts_at_utc'];$pdo->prepare('UPDATE meetings SET title=?,starts_at_utc=?,location=?,note=?,updated_by=?,updated_at=CURRENT_TIMESTAMP,reminder_sent_at=NULL WHERE id=?')->execute([$title,$date,trim((string)$_POST['location']),trim((string)$_POST['note']),$u['id'],$m['id']]);meeting_audit($pdo,$m['id'],$u['id'],'details_updated',$changed?'Termin geändert':null);if($changed)sm_push($pdo,'Stammtisch-Termin geändert',$title.' · '.meeting_display($date));flash('success','Details gespeichert.');}
     elseif($action==='agenda_add'){$title=trim((string)$_POST['title']);if(mb_strlen($title)<2)throw new RuntimeException('TOP benennen.');$q=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0) FROM meeting_agenda_items WHERE meeting_id=?');$q->execute([$m['id']]);$pdo->prepare('INSERT INTO meeting_agenda_items(meeting_id,title,sort_order,updated_by) VALUES(?,?,?,?)')->execute([$m['id'],$title,(int)$q->fetchColumn()+10,$u['id']]);flash('success','TOP hinzugefügt.');}
     elseif($action==='agenda_delete'){$pdo->prepare('DELETE FROM meeting_agenda_items WHERE id=? AND meeting_id=?')->execute([(int)$_POST['item_id'],$m['id']]);flash('success','TOP gelöscht.');}
     elseif($action==='agenda_order'){$ids=array_filter(array_map('intval',explode(',',(string)$_POST['order'])));sm_order($pdo,$m['id'],$ids);flash('success','Reihenfolge gespeichert.');}
     elseif($action==='suggestion'){$q=$pdo->prepare("SELECT * FROM meeting_topic_suggestions WHERE id=? AND meeting_id=? AND status='pending'");$q->execute([(int)$_POST['suggestion_id'],$m['id']]);$s=$q->fetch();if(!$s)throw new RuntimeException('Vorschlag nicht gefunden.');$accept=$_POST['decision']==='accept';$pdo->prepare('UPDATE meeting_topic_suggestions SET status=?,decided_by=?,decided_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$accept?'accepted':'rejected',$u['id'],$s['id']]);if($accept){$q=$pdo->prepare('SELECT COALESCE(MAX(sort_order),0) FROM meeting_agenda_items WHERE meeting_id=?');$q->execute([$m['id']]);$pdo->prepare('INSERT INTO meeting_agenda_items(meeting_id,title,sort_order,updated_by) VALUES(?,?,?,?)')->execute([$m['id'],$s['title'],(int)$q->fetchColumn()+10,$u['id']]);}flash('success',$accept?'Thema übernommen.':'Vorschlag abgelehnt.');}
     elseif($action==='attendees'){$ids=array_unique(array_map('intval',(array)($_POST['attendees']??[])));$pdo->beginTransaction();$pdo->prepare('DELETE FROM meeting_attendees WHERE meeting_id=?')->execute([$m['id']]);$q=$pdo->prepare('INSERT INTO meeting_attendees(meeting_id,user_id,updated_by) SELECT ?,id,? FROM users WHERE id=? AND is_active=1');foreach($ids as $id)$q->execute([$m['id'],$u['id'],$id]);$pdo->commit();flash('success','Anwesenheit gespeichert.');}
     elseif($action==='protocol'){$html=protocol_sanitize_html((string)$_POST['html']);$pdo->prepare('UPDATE meeting_agenda_items SET protocol_html=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND meeting_id=?')->execute([$html,$u['id'],(int)$_POST['item_id'],$m['id']]);flash('success','Protokoll gespeichert.');}
     elseif($action==='complete'){if($_POST['confirm']!=='abschluss')throw new RuntimeException('Sicherheitsabfrage nicht bestätigt.');$pdo->prepare("UPDATE meetings SET status='completed',completed_at=CURRENT_TIMESTAMP,completed_by=?,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE id=?")->execute([$u['id'],$u['id'],$m['id']]);meeting_audit($pdo,$m['id'],$u['id'],'completed','Abgeschlossen');flash('success','Stammtisch abgeschlossen und Protokoll eingefroren.');}
