if($m){$q=$pdo->prepare("SELECT o.id,o.starts_at_utc,COUNT(v.user_id) votes,string_agg(TRIM(u.first_name||' '||u.last_name),', ' ORDER BY u.last_name,u.first_name) voters FROM meeting_poll_options o LEFT JOIN meeting_votes v ON v.option_id=o.id LEFT JOIN users u ON u.id=v.user_id WHERE o.meeting_id=? GROUP BY o.id ORDER BY o.starts_at_utc");$q->execute([$m['id']]);$options=$q->fetchAll();if($m['status']==='poll'){$q=$pdo->prepare('SELECT v.option_id FROM meeting_votes v JOIN meeting_poll_options o ON o.id=v.option_id WHERE o.meeting_id=? AND v.user_id=?');$q->execute([$m['id'],$u['id']]);$myVotes=array_flip(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)));}$q=$pdo->prepare('SELECT a.*,u.first_name,u.last_name FROM meeting_agenda_items a LEFT JOIN users u ON u.id=a.updated_by WHERE a.meeting_id=? ORDER BY a.sort_order,a.id');$q->execute([$m['id']]);$agenda=$q->fetchAll();$q=$pdo->prepare("SELECT s.*,u.first_name,u.last_name FROM meeting_topic_suggestions s JOIN users u ON u.id=s.suggested_by WHERE s.meeting_id=? AND s.status='pending' ORDER BY s.id");$q->execute([$m['id']]);$suggestions=$q->fetchAll();if($canManage){$members=$pdo->query('SELECT id,first_name,last_name FROM users WHERE is_active=1 ORDER BY last_name,first_name')->fetchAll();$q=$pdo->prepare('SELECT user_id FROM meeting_attendees WHERE meeting_id=?');$q->execute([$m['id']]);$present=array_flip(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)));}}
