button type="button" data-image>Bild</button><input type="file" accept="image/jpeg,image/png,image/webp" hidden></div><div class="wysiwyg-editor" contenteditable="true"><?=protocol_body_html($a['protocol_html'])?></div><textarea name="html" hidden></textarea><button class="btn btn-sm btn-outline-secondary mt-2">Protokoll speichern</button></form><?php elseif($a['protocol_html']):?><div class="news-body mt-3"><?=protocol_body_html($a['protocol_html'])?></div><?php endif;?></article><?php endforeach;?></div><?php if($canManage):?><form method="post" id="order"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="agenda_order"><input type="hidden" name="meeting_id" value="<?=$m['id']?>"><input type="hidden" name="order"><button class="btn btn-sm btn-outline-secondary">Reihenfolge speichern</button></form><?php endif;?></div>
