<script>document.querySelectorAll('.protocol-editor').forEach(f=>{let e=f.querySelector('.wysiwyg-editor'),o=f.querySelector('textarea'),i=f.querySelector('input[type=file]');f.onsubmit=()=>o.value=e.innerHTML;f.querySelectorAll('[data-cmd]').forEach(b=>b.onclick=()=>{e.focus();document.execCommand(b.dataset.cmd,false,null)});f.querySelector('[data-image]').onclick=()=>i.click();i.onchange=async()=>{let d=new FormData();d.append('csrf','<?=e(csrf_token())?>');d.append('meeting_id','<?=$m['id']??0?>');d.append('image',i.files[0]);let r=await fetch('/meeting-image-upload.php',{method:'POST',body:d}),j=await r.json();if(!r.ok||!j.ok)return alert(j.error||'Upload fehlgeschlagen');e.focus();document.execCommand('insertImage',false,j.url)}});let l=document.querySelector('[data-sortable]'),drag;if(l){l.querySelectorAll('[draggable=true]').forEach(x=>{x.ondragstart=()=>drag=x;x.ondragover=e=>{e.preventDefault();if(drag&&drag!==x)l.insertBefore(drag,e.clientY<x.getBoundingClientRect().top+x.offsetHeight/2?x:x.nextSibling)}});let f=document.querySelector('#order');if(f)f.onsubmit=()=>f.querySelector('[name=order]').value=[...l.children].map(x=>x.dataset.id).join(',')}</script>
